// Fichier généré par tools/build-admin.mjs — ne pas modifier à la main.
export const ADMIN_FILES = {
 "admin.css": {
  "type": "text/css; charset=utf-8",
  "body": ":root {\n  --bg: #0b1310; --panel: #111d18; --panel-2: #16261f; --line: rgba(230, 192, 104, .16);\n  --or: #e6c068; --or-2: #b8862b; --rouge: #c8102e; --vert: #2f8a5b; --texte: #f1eee6; --muted: rgba(241, 238, 230, .6);\n  --sans: system-ui, -apple-system, \"Segoe UI\", Roboto, Arial, sans-serif;\n  --serif: \"Playfair Display\", Georgia, serif;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; font-family: var(--sans); background: var(--bg); color: var(--texte); font-size: 15px; }\n[hidden] { display: none !important; }\na { color: var(--or); }\n.muted { color: var(--muted); }\n\ninput, select, textarea {\n  width: 100%; padding: 10px 12px; border-radius: 10px; font: inherit; color: var(--texte);\n  background: #0a1411; border: 1px solid rgba(255, 255, 255, .12);\n}\ninput:focus, select:focus, textarea:focus { outline: 2px solid var(--or); outline-offset: 0; border-color: transparent; }\ntextarea { resize: vertical; min-height: 90px; }\nlabel { display: grid; gap: 6px; font-size: 13px; font-weight: 600; color: var(--muted); }\ninput[type=checkbox] { width: auto; accent-color: var(--or); transform: scale(1.2); }\n.check { display: flex; align-items: center; gap: 10px; color: var(--texte); font-weight: 500; font-size: 14px; }\n\n.btn-primary, .btn, .btn-danger {\n  border: 0; border-radius: 10px; padding: 10px 18px; font: inherit; font-weight: 700; cursor: pointer;\n  color: #2a1c05; background: linear-gradient(180deg, #fff0bf, var(--or) 50%, var(--or-2));\n}\n.btn { background: var(--panel-2); color: var(--texte); border: 1px solid var(--line); font-weight: 600; }\n.btn-danger { background: rgba(200, 16, 46, .15); color: #ff8b9d; border: 1px solid rgba(200, 16, 46, .4); font-weight: 600; padding: 6px 12px; }\nbutton:disabled { opacity: .6; cursor: wait; }\n\n/* ----- Connexion ----- */\n.login-page { min-height: 100vh; display: grid; place-items: center; padding: 20px;\n  background: radial-gradient(ellipse at top, rgba(230, 192, 104, .12), transparent 60%), var(--bg); }\n.login-card { width: min(380px, 100%); display: grid; gap: 16px; padding: 34px 28px; border-radius: 20px;\n  background: var(--panel); border: 1px solid var(--line); box-shadow: 0 30px 60px rgba(0, 0, 0, .5); }\n.login-card h1 { margin: 0; font-family: var(--serif); color: var(--or); font-size: 26px; }\n.login-card .muted { margin: -10px 0 4px; }\n.login-logo { font-size: 36px; }\n.error { margin: 0; padding: 10px 12px; border-radius: 10px; background: rgba(200, 16, 46, .15); border: 1px solid rgba(200, 16, 46, .4); color: #ffb3bf; font-size: 14px; }\n.back { font-size: 13px; text-align: center; text-decoration: none; color: var(--muted); }\n\n/* ----- Tableau de bord ----- */\n.layout { display: grid; grid-template-columns: 230px 1fr; min-height: 100vh; }\n.side { background: var(--panel); border-right: 1px solid var(--line); padding: 22px 14px; display: flex; flex-direction: column; gap: 4px; position: sticky; top: 0; height: 100vh; }\n.side .brand { font-family: var(--serif); color: var(--or); font-size: 19px; padding: 0 10px 18px; }\n.side button.tab { text-align: left; background: none; border: 0; color: var(--muted); font: inherit; padding: 10px 12px; border-radius: 10px; cursor: pointer; font-weight: 600; }\n.side button.tab:hover { background: var(--panel-2); color: var(--texte); }\n.side button.tab.active { background: rgba(230, 192, 104, .12); color: var(--or); }\n.side .spacer { flex: 1; }\n.side .who { font-size: 12px; color: var(--muted); padding: 0 10px 8px; word-break: break-all; }\n.side a.view { padding: 10px 12px; font-size: 14px; text-decoration: none; }\nmain.content { padding: 28px 32px 60px; max-width: 1200px; width: 100%; min-width: 0; }\nh2 { font-family: var(--serif); margin: 0 0 6px; font-size: 28px; }\nh3 { margin: 0 0 14px; font-size: 16px; }\n.lead { color: var(--muted); margin: 0 0 22px; }\n\n.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 14px; margin-bottom: 24px; }\n.stat { background: var(--panel); border: 1px solid var(--line); border-radius: 14px; padding: 16px 18px; }\n.stat span { display: block; font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }\n.stat strong { display: block; font-size: 30px; margin-top: 6px; color: var(--or); font-variant-numeric: tabular-nums; }\n\n.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 16px; padding: 20px; margin-bottom: 22px; }\n.toolbar { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; margin-bottom: 14px; }\n.toolbar label { min-width: 160px; }\n.table-wrap { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; font-size: 14px; }\nth, td { padding: 10px 10px; text-align: left; border-bottom: 1px solid rgba(255, 255, 255, .06); white-space: nowrap; }\nth { color: var(--muted); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: .06em; }\ntd.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }\ntr.today td { background: rgba(230, 192, 104, .07); }\n.pill { display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; }\n.pill.oui { background: rgba(230, 192, 104, .18); color: var(--or); }\n.pill.non { background: rgba(255, 255, 255, .06); color: var(--muted); }\n.stat.warn strong { color: #ffd98a; }\n.status { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 700; }\n.status.attente { background: rgba(255, 217, 138, .15); color: #ffd98a; }\n.status.validee { background: rgba(127, 214, 164, .15); color: #8ee0ad; }\n.status.refusee { background: rgba(200, 16, 46, .18); color: #ff9aa9; }\n.row-actions { display: flex; gap: 6px; }\n.btn-ok { border: 1px solid rgba(127, 214, 164, .45); background: rgba(127, 214, 164, .12); color: #8ee0ad; border-radius: 10px; padding: 6px 12px; font: inherit; font-weight: 600; cursor: pointer; }\n.btn-no { border: 1px solid rgba(255, 154, 169, .4); background: rgba(200, 16, 46, .12); color: #ff9aa9; border-radius: 10px; padding: 6px 12px; font: inherit; font-weight: 600; cursor: pointer; }\n.btn-ghost { border: 1px solid rgba(255, 255, 255, .12); background: none; color: var(--muted); border-radius: 10px; padding: 6px 10px; font: inherit; cursor: pointer; }\n.code { font-family: ui-monospace, Menlo, Consolas, monospace; letter-spacing: .04em; }\n.empty { color: var(--muted); text-align: center; padding: 28px; }\n\n.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }\n.form-grid .full { grid-column: 1 / -1; }\n.hint { font-weight: 400; font-size: 12px; color: var(--muted); }\n.actions { display: flex; gap: 10px; align-items: center; margin-top: 18px; }\n.saved { color: #7fd6a4; font-size: 14px; }\n\n.case-list { display: grid; gap: 10px; }\n.case-item { background: var(--panel); border: 1px solid var(--line); border-radius: 14px; overflow: hidden; }\n.case-item summary { cursor: pointer; padding: 14px 18px; display: flex; gap: 14px; align-items: center; list-style: none; }\n.case-item summary::-webkit-details-marker { display: none; }\n.case-item .d { width: 38px; height: 38px; border-radius: 10px; display: grid; place-items: center; font-weight: 800; color: var(--or); background: #0f3b2b; border: 1px solid rgba(230, 192, 104, .3); flex: none; }\n.case-item .t { flex: 1; min-width: 0; }\n.case-item .t b { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.case-item .t small { color: var(--muted); }\n.case-item[open] summary { border-bottom: 1px solid var(--line); }\n.case-item form { padding: 18px; }\n\n.draw-stage { text-align: center; padding: 30px 20px; border-radius: 16px; margin-top: 16px;\n  background: radial-gradient(circle at center, rgba(230, 192, 104, .14), transparent 70%), #0a1411; border: 1px solid var(--line); }\n.draw-name { font-family: var(--serif); font-size: clamp(30px, 5vw, 52px); color: var(--or); margin: 6px 0; min-height: 1.2em; }\n.draw-name.rolling { color: var(--muted); }\n.draw-meta { color: var(--muted); }\n\n.toast { position: fixed; bottom: 22px; right: 22px; padding: 12px 18px; border-radius: 12px; background: #1b2b24; border: 1px solid var(--line); box-shadow: 0 12px 30px rgba(0, 0, 0, .5); z-index: 10; }\n.toast.err { border-color: rgba(200, 16, 46, .6); color: #ffb3bf; }\n\n@media (max-width: 820px) {\n  .layout { grid-template-columns: 1fr; }\n  .side { position: static; height: auto; flex-direction: row; flex-wrap: wrap; padding: 12px; }\n  .side .brand { width: 100%; padding-bottom: 8px; }\n  .side .spacer { display: none; }\n  main.content { padding: 20px 16px 50px; }\n  .form-grid { grid-template-columns: 1fr; }\n}\n.mt { margin-top: 24px; }\n\n.edit-card { width: min(560px, 100%); margin: 0; }\n.edit-total { margin: 16px 0 0; font-size: 18px; font-weight: 700; color: var(--or); }\n.btn-edit { border: 1px solid var(--line); background: rgba(230, 192, 104, .1); color: var(--or); border-radius: 10px; padding: 6px 10px; font: inherit; font-weight: 600; cursor: pointer; }\n.hint.full { grid-column: 1 / -1; margin: 0; }\n\n/* ----- Retour au calendrier ----- */\n.back-home { display: block; margin: 0 4px 16px; padding: 11px 14px; border-radius: 12px; text-align: center; text-decoration: none; font-weight: 700;\n  color: #2a1c05; background: linear-gradient(180deg, #fff0bf, var(--or) 50%, var(--or-2)); box-shadow: 0 6px 16px rgba(230, 192, 104, .25); }\n.back-home:hover { filter: brightness(1.05); }\n\n/* ----- Roue ----- */\n.wheel-layout { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 22px; align-items: start; }\n.wheel-panel { display: flex; flex-direction: column; align-items: center; gap: 14px; }\n.wheel-box { position: relative; width: min(100%, 520px); aspect-ratio: 1; }\n.wheel-box canvas { width: 100%; height: 100%; display: block; filter: drop-shadow(0 14px 30px rgba(0, 0, 0, .55)); }\n.wheel-pointer { position: absolute; top: -6px; left: 50%; transform: translateX(-50%); z-index: 2; width: 0; height: 0;\n  border-left: 18px solid transparent; border-right: 18px solid transparent; border-top: 34px solid var(--or); filter: drop-shadow(0 4px 6px rgba(0, 0, 0, .6)); }\n.wheel-center { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 22%; aspect-ratio: 1; border-radius: 50%; z-index: 2;\n  border: 4px solid #fff3c4; cursor: pointer; font: inherit; font-weight: 800; font-size: clamp(11px, 1.6vw, 15px); letter-spacing: .06em; color: #2a1c05;\n  background: radial-gradient(circle at 35% 30%, #fff6d6, var(--or) 55%, var(--or-2)); box-shadow: 0 6px 18px rgba(0, 0, 0, .5); }\n.wheel-center:disabled, .btn-big:disabled { opacity: .7; cursor: wait; }\n.wheel-live { font-family: var(--serif); font-size: 26px; color: var(--or); min-height: 1.3em; text-align: center; }\n.btn-big { font-size: 18px; padding: 14px 28px; }\n.wheel-controls { display: grid; gap: 14px; }\n.wheel-controls hr { border: 0; border-top: 1px solid var(--line); margin: 2px 0; width: 100%; }\n.add-row { display: flex; gap: 8px; }\n.add-row input { flex: 1; }\n.add-block { display: grid; grid-template-columns: 1fr auto auto; gap: 10px; align-items: end; }\n@media (max-width: 520px) { .add-block { grid-template-columns: 1fr 1fr; } .add-block label:first-child { grid-column: 1 / -1; } }\n.tk-stepper { display: flex; align-items: stretch; }\n.tk-stepper input { width: 74px; text-align: center; border-radius: 0; font-weight: 700; -moz-appearance: textfield; }\n.tk-stepper input::-webkit-outer-spin-button, .tk-stepper input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }\n.tk-btn { width: 36px; border: 1px solid rgba(255, 255, 255, .12); background: var(--panel-2); color: var(--texte); font: inherit; font-size: 18px; font-weight: 700; cursor: pointer; }\n.tk-btn:first-child { border-radius: 10px 0 0 10px; } .tk-btn:last-child { border-radius: 0 10px 10px 0; }\n.tk-btn:hover { background: rgba(230, 192, 104, .15); color: var(--or); }\n.tk-quick { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }\n.tk-quick button { border: 1px solid var(--line); background: var(--panel-2); color: var(--texte); border-radius: 999px; padding: 4px 12px; font: inherit; font-size: 13px; font-weight: 600; cursor: pointer; }\n.tk-quick button.on, .tk-quick button:hover { border-color: var(--or); color: var(--or); background: rgba(230, 192, 104, .12); }\n.chips { display: flex; flex-wrap: wrap; gap: 8px; }\n.chip .chip-tk { display: inline-flex; align-items: center; gap: 2px; margin-left: 4px; padding: 1px 4px; border-radius: 999px; background: rgba(230, 192, 104, .14); color: var(--or); font-weight: 700; font-size: 12px; }\n.chip .chip-tk button { width: 20px; height: 20px; font-size: 13px; background: rgba(0, 0, 0, .25); color: var(--or); }\n.chip .chip-tk button:hover { background: rgba(230, 192, 104, .3); color: #fff; }\n.chip { display: inline-flex; align-items: center; gap: 6px; padding: 5px 6px 5px 12px; border-radius: 999px; font-size: 13px; background: var(--panel-2); border: 1px solid var(--line); }\n.chip button { border: 0; background: rgba(255, 255, 255, .08); color: var(--muted); width: 22px; height: 22px; border-radius: 50%; cursor: pointer; font-size: 14px; line-height: 1; }\n.chip button:hover { background: rgba(200, 16, 46, .4); color: #fff; }\n.wheel-count { margin: 0; font-weight: 600; }\n.ok-pill { color: #8ee0ad; font-weight: 600; } .no-pill { color: var(--muted); }\n\n/* ----- Annonce du gagnant ----- */\n.winner-overlay { position: fixed; inset: 0; z-index: 20; display: grid; place-items: center; padding: 20px;\n  background: radial-gradient(circle at center, rgba(230, 192, 104, .22), rgba(3, 8, 6, .9) 65%); backdrop-filter: blur(5px); }\n#w-confetti { position: fixed; inset: 0; width: 100%; height: 100%; pointer-events: none; }\n.winner-card { position: relative; width: min(620px, 100%); text-align: center; padding: 34px 26px 24px; border-radius: 26px;\n  background: linear-gradient(170deg, #4a0c18, #1c050c); border: 2px solid var(--or);\n  box-shadow: 0 0 0 6px rgba(230, 192, 104, .15), 0 30px 90px rgba(0, 0, 0, .7), 0 0 120px rgba(230, 192, 104, .35);\n  animation: winpop .8s cubic-bezier(.2, 1.4, .4, 1); }\n@keyframes winpop { from { opacity: 0; transform: scale(.4) rotate(-5deg); } }\n.winner-emoji { font-size: 64px; line-height: 1; }\n.winner-eyebrow { margin: 10px 0 0; letter-spacing: .3em; text-transform: uppercase; font-size: 13px; color: var(--or); }\n.winner-name { font-family: var(--serif); font-weight: 700; font-size: clamp(40px, 8vw, 76px); line-height: 1.1; margin: 6px 0;\n  word-break: break-all; background: linear-gradient(180deg, #fff6d6, var(--or) 60%, var(--or-2)); -webkit-background-clip: text; background-clip: text; color: transparent; }\n.winner-meta { color: var(--muted); margin: 0 0 20px; }\n.winner-actions { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; }\n.winner-note { min-height: 1.2em; margin: 14px 0 6px; font-size: 14px; color: #8ee0ad; }\n@media (max-width: 980px) { .wheel-layout { grid-template-columns: 1fr; } }\n"
 },
 "admin.html": {
  "type": "text/html; charset=utf-8",
  "body": "<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <title>Administration · Calendrier</title>\n  <link rel=\"stylesheet\" href=\"/admin/admin.css\">\n  <script type=\"module\" src=\"/admin/admin.js\"></script>\n</head>\n<body>\n<div class=\"layout\">\n  <nav class=\"side\">\n    <div class=\"brand\">🎄 Administration</div>\n    <a class=\"back-home\" href=\"/\">← Retour au calendrier</a>\n    <button class=\"tab active\" data-tab=\"dashboard\">Tableau de bord</button>\n    <button class=\"tab\" data-tab=\"participants\">Participants & tickets</button>\n    <button class=\"tab\" data-tab=\"draw\">🎡 Roue du tirage</button>\n    <button class=\"tab\" data-tab=\"cases\">Cases & lots</button>\n    <button class=\"tab\" data-tab=\"settings\">Réglages</button>\n    <button class=\"tab\" data-tab=\"account\">Compte</button>\n    <div class=\"spacer\"></div>\n    <div class=\"who\" id=\"who\"></div>\n    <a class=\"view\" href=\"/\" target=\"_blank\" rel=\"noopener\">Ouvrir le calendrier dans un nouvel onglet ↗</a>\n    <button class=\"tab\" id=\"logout\">Se déconnecter</button>\n  </nav>\n\n  <main class=\"content\">\n    <!-- Tableau de bord -->\n    <section data-panel=\"dashboard\">\n      <h2>Tableau de bord</h2>\n      <p class=\"lead\" id=\"today-line\"></p>\n      <div class=\"cards\">\n        <div class=\"stat\"><span>Visiteurs aujourd’hui</span><strong id=\"s-visitors-today\">–</strong></div>\n        <div class=\"stat\"><span>Visiteurs au total</span><strong id=\"s-visitors\">–</strong></div>\n        <div class=\"stat\"><span>Pages vues</span><strong id=\"s-views\">–</strong></div>\n        <div class=\"stat\"><span>Participants uniques</span><strong id=\"s-participants\">–</strong></div>\n        <div class=\"stat\"><span>Participations</span><strong id=\"s-participations\">–</strong></div>\n        <div class=\"stat\"><span>Tickets distribués</span><strong id=\"s-tickets\">–</strong></div>\n        <div class=\"stat warn\"><span>À valider</span><strong id=\"s-pending\">–</strong></div>\n        <div class=\"stat\"><span>Validées</span><strong id=\"s-validated\">–</strong></div>\n      </div>\n      <div class=\"panel\">\n        <h3>Par jour</h3>\n        <div class=\"table-wrap\"><table>\n          <thead><tr><th>Jour</th><th>Lot</th><th class=\"num\">Ouvertures</th><th class=\"num\">Participants</th><th class=\"num\">À valider</th><th class=\"num\">Validées</th><th class=\"num\">Tickets</th><th>Gagnant</th></tr></thead>\n          <tbody id=\"by-day\"></tbody>\n        </table></div>\n      </div>\n      <div class=\"panel\">\n        <h3>Visites du site</h3>\n        <p class=\"hint\">Visiteurs uniques (par appareil) et nombre de pages vues, par date.</p>\n        <div class=\"table-wrap\"><table>\n          <thead><tr><th>Date</th><th class=\"num\">Visiteurs</th><th class=\"num\">Pages vues</th></tr></thead>\n          <tbody id=\"visits\"></tbody>\n        </table></div>\n      </div>\n    </section>\n\n    <!-- Participants -->\n    <section data-panel=\"participants\" hidden>\n      <h2>Participants & tickets</h2>\n      <p class=\"lead\">Toutes les personnes qui ont activé leur récompense. Vérifie leurs infos sur TikTok, puis valide ou refuse chaque participation. Seules les participations validées comptent pour le tirage.</p>\n      <div class=\"panel\">\n        <div class=\"toolbar\">\n          <label>Jour\n            <select id=\"p-day\"><option value=\"\">Tous les jours</option></select>\n          </label>\n          <label>Statut\n            <select id=\"p-status\">\n              <option value=\"\">Tous</option>\n              <option value=\"attente\">⏳ À valider</option>\n              <option value=\"validee\">✅ Validées</option>\n              <option value=\"refusee\">❌ Refusées</option>\n            </select>\n          </label>\n          <label>Rechercher un pseudo\n            <input id=\"p-search\" placeholder=\"pseudo…\">\n          </label>\n          <button class=\"btn\" id=\"p-refresh\">Actualiser</button>\n          <button class=\"btn\" id=\"p-validate-all\">✅ Tout valider pour ce jour</button>\n          <a class=\"btn\" id=\"p-csv\" href=\"/api/admin/participations.csv\">Exporter (CSV / Excel)</a>\n        </div>\n        <p class=\"hint\" id=\"p-summary\"></p>\n        <div class=\"table-wrap\"><table>\n          <thead><tr><th>Jour</th><th>Pseudo TikTok</th><th class=\"num\">Cœur du jour</th><th>Super Fan</th><th class=\"num\">Pièces</th><th class=\"num\">Mérite</th><th class=\"num\">Tickets</th><th>Code ticket</th><th>Statut</th><th>Date</th><th>Actions</th></tr></thead>\n          <tbody id=\"p-rows\"></tbody>\n        </table></div>\n      </div>\n      <div class=\"winner-overlay\" id=\"edit-box\" hidden>\n        <form class=\"panel edit-card\" id=\"edit-form\">\n          <h3 id=\"edit-title\">Modifier la participation</h3>\n          <div class=\"form-grid\">\n            <label>Niveau du Cœur du jour <input name=\"hearts\" type=\"number\" min=\"0\"></label>\n            <label>Pièces envoyées <input name=\"coins\" type=\"number\" min=\"0\"></label>\n            <label class=\"check full\"><input type=\"checkbox\" name=\"top_fan\"> Super Fan</label>\n            <label class=\"full\">🏆 Tickets mérite <span class=\"hint\">Tickets en plus pour l’implication : likes, présence, participation… (peut être négatif pour retirer des tickets)</span>\n              <input name=\"bonus\" type=\"number\"></label>\n          </div>\n          <p class=\"edit-total\" id=\"edit-total\"></p>\n          <div class=\"actions\">\n            <button class=\"btn-primary\" type=\"submit\">Enregistrer</button>\n            <button class=\"btn\" type=\"button\" id=\"edit-cancel\">Annuler</button>\n          </div>\n        </form>\n      </div>\n    </section>\n\n    <!-- Tirage -->\n    <section data-panel=\"draw\" hidden>\n      <h2>Roue du tirage 🎡</h2>\n      <p class=\"lead\">La roue se remplit avec les tickets de la case choisie. Tu peux aussi ajouter des pseudos à la main. Plus une personne a de tickets, plus sa part de roue est grande.</p>\n      <div class=\"wheel-layout\">\n        <div class=\"panel wheel-panel\">\n          <div class=\"wheel-box\">\n            <div class=\"wheel-pointer\" aria-hidden=\"true\"></div>\n            <canvas id=\"wheel\" width=\"560\" height=\"560\" aria-label=\"Roue du tirage\"></canvas>\n            <button class=\"wheel-center\" id=\"w-spin-center\" type=\"button\">TOURNER</button>\n          </div>\n          <div class=\"wheel-live\" id=\"w-live\">—</div>\n          <button class=\"btn-primary btn-big\" id=\"w-spin\" type=\"button\">🎡 Faire tourner la roue</button>\n        </div>\n        <div class=\"panel wheel-controls\">\n          <label>Case / jour\n            <select id=\"d-day\"></select>\n          </label>\n          <p class=\"hint\" id=\"d-reward\"></p>\n          <label class=\"check\"><input type=\"checkbox\" id=\"w-auto\" checked> Ajouter automatiquement les tickets de cette case</label>\n          <label class=\"check\"><input type=\"checkbox\" id=\"d-validated\" checked> Seulement les participations validées</label>\n          <label class=\"check\"><input type=\"checkbox\" id=\"d-exclude\"> Exclure les gagnants déjà confirmés</label>\n          <hr>\n          <div class=\"add-block\">\n            <label>Ajouter un pseudo à la main\n              <input id=\"w-add-input\" placeholder=\"pseudo TikTok\" maxlength=\"400\">\n            </label>\n            <label class=\"tk-label\">Tickets\n              <span class=\"tk-stepper\">\n                <button type=\"button\" class=\"tk-btn\" id=\"w-tk-minus\" aria-label=\"Un ticket de moins\">−</button>\n                <input id=\"w-add-tickets\" type=\"number\" min=\"1\" max=\"100000\" value=\"1\" inputmode=\"numeric\">\n                <button type=\"button\" class=\"tk-btn\" id=\"w-tk-plus\" aria-label=\"Un ticket de plus\">+</button>\n              </span>\n            </label>\n            <button class=\"btn-primary\" id=\"w-add\" type=\"button\">Ajouter</button>\n          </div>\n          <div class=\"tk-quick\" id=\"w-tk-quick\">\n            <span class=\"hint\">Rapide :</span>\n            <button type=\"button\" data-tk=\"1\">1</button><button type=\"button\" data-tk=\"5\">5</button><button type=\"button\" data-tk=\"10\">10</button>\n            <button type=\"button\" data-tk=\"20\">20</button><button type=\"button\" data-tk=\"50\">50</button><button type=\"button\" data-tk=\"100\">100</button>\n          </div>\n          <p class=\"hint\">Astuce : colle plusieurs pseudos d’un coup, séparés par des virgules ou des retours à la ligne. Ils reçoivent tous ce nombre de tickets. Tu peux aussi écrire <b>pseudo:15</b> pour donner 15 tickets à une personne précise. Si la personne a déjà des tickets sur la roue, ceux-ci s’ajoutent.</p>\n          <div class=\"chips\" id=\"w-manual\"></div>\n          <button class=\"btn-ghost\" id=\"w-clear\" type=\"button\">Vider les ajouts manuels</button>\n          <hr>\n          <p class=\"wheel-count\" id=\"w-count\"></p>\n        </div>\n      </div>\n\n      <div class=\"panel\">\n        <h3>Gagnants confirmés</h3>\n        <div class=\"table-wrap\"><table>\n          <thead><tr><th>Jour</th><th>Lot</th><th>Gagnant</th><th>Code ticket</th><th>Message sur le site</th><th>Date</th><th></th></tr></thead>\n          <tbody id=\"d-history\"></tbody>\n        </table></div>\n      </div>\n\n      <div class=\"winner-overlay\" id=\"w-result\" hidden>\n        <canvas id=\"w-confetti\" aria-hidden=\"true\"></canvas>\n        <div class=\"winner-card\">\n          <div class=\"winner-emoji\">🎉</div>\n          <p class=\"winner-eyebrow\">Le gagnant est</p>\n          <div class=\"winner-name\" id=\"w-name\"></div>\n          <p class=\"winner-meta\" id=\"w-meta\"></p>\n          <div class=\"winner-actions\">\n            <button class=\"btn\" id=\"w-copy\" type=\"button\">📋 Copier le pseudo</button>\n            <button class=\"btn-primary\" id=\"w-confirm\" type=\"button\">✅ Confirmer ce gagnant</button>\n            <button class=\"btn\" id=\"w-again\" type=\"button\">🔄 Relancer la roue</button>\n          </div>\n          <p class=\"winner-note\" id=\"w-note\"></p>\n          <button class=\"btn-ghost\" id=\"w-close\" type=\"button\">Fermer</button>\n        </div>\n      </div>\n    </section>\n\n    <!-- Cases -->\n    <section data-panel=\"cases\" hidden>\n      <h2>Cases & lots</h2>\n      <p class=\"lead\">Modifie le contenu de chaque case : titre, message, lot, image et lien.</p>\n      <div class=\"case-list\" id=\"case-list\"></div>\n    </section>\n\n    <!-- Réglages -->\n    <section data-panel=\"settings\" hidden>\n      <h2>Réglages</h2>\n      <p class=\"lead\">Nom du calendrier, dates, participations et règles des tickets.</p>\n      <form class=\"panel\" id=\"settings-form\">\n        <h3>Apparence</h3>\n        <div class=\"form-grid\">\n          <label class=\"full\">Nom du calendrier <input name=\"app_name\" maxlength=\"80\" required></label>\n          <label class=\"full\">Sous-titre <input name=\"subtitle\" maxlength=\"200\"></label>\n          <label class=\"full\">Texte du bas de page <input name=\"footer_text\" maxlength=\"300\"></label>\n        </div>\n        <h3 class=\"mt\">Réseaux (affichés sur la page d’accueil)</h3>\n        <div class=\"form-grid\">\n          <label class=\"full\">Lien de ta chaîne TikTok <input name=\"tiktok_url\" type=\"url\" placeholder=\"https://www.tiktok.com/@…\"></label>\n          <label class=\"full\">Lien d’invitation Discord <input name=\"discord_url\" type=\"url\" placeholder=\"https://discord.gg/…\"></label>\n          <p class=\"hint full\">Laisse un champ vide pour cacher le bouton.</p>\n        </div>\n        <h3 class=\"mt\">Message au gagnant</h3>\n        <div class=\"form-grid\">\n          <label class=\"full\">Ton pseudo <span class=\"hint\">Affiché dans le message du gagnant : « … t’a envoyé un message sur TikTok ».</span>\n            <input name=\"creator_name\" maxlength=\"40\" placeholder=\"MXOU\"></label>\n        </div>\n        <h3 class=\"mt\">Musique</h3>\n        <div class=\"form-grid\">\n          <label class=\"check full\"><input type=\"checkbox\" name=\"music_enabled\"> Jouer une musique de Noël sur le calendrier</label>\n          <label class=\"full\">Musique\n            <select name=\"music_track\">\n              <option value=\"ambiance\">Ambiance de Noël (douce, recommandée)</option>\n              <option value=\"jinglelive\">Jingle Bells (comme la vidéo)</option>\n              <option value=\"deckhalls\">Deck the Halls</option>\n              <option value=\"wewish\">We Wish You a Merry Christmas</option>\n              <option value=\"jingle\">Jingle Bells</option>\n              <option value=\"doucenuit\">Douce nuit</option>\n            </select>\n          </label>\n          <label class=\"full\">Lien d’un fichier MP3 (optionnel) <span class=\"hint\">Remplace la musique choisie au-dessus. Utilise uniquement une musique que tu as le droit de diffuser.</span>\n            <input name=\"music_url\" type=\"url\" placeholder=\"https://…/musique.mp3\"></label>\n        </div>\n        <h3 class=\"mt\">Dates</h3>\n        <div class=\"form-grid\">\n          <label>Année du calendrier <input name=\"year\" type=\"number\" min=\"2024\" max=\"2100\" required></label>\n          <label>Fuseau horaire <input name=\"timezone\" placeholder=\"Europe/Paris\"></label>\n          <label class=\"full\">Date de test <span class=\"hint\">Pour essayer le calendrier avant décembre. Laisse vide pour utiliser la vraie date. ⚠️ Les viewers voient aussi cette date.</span>\n            <input name=\"test_date\" type=\"date\">\n          </label>\n        </div>\n        <h3 class=\"mt\">Participations & tickets</h3>\n        <div class=\"form-grid\">\n          <label class=\"check full\"><input type=\"checkbox\" name=\"participation_open\"> Les viewers peuvent activer leur récompense</label>\n          <p class=\"hint full\">❤️ <b>Cœur du jour</b> : tickets = niveau × multiplicateur du palier. Exemple avec les réglages par défaut : niveau 5 = 5 tickets, niveau 12 = 24 tickets, niveau 30 = 90 tickets.</p>\n          <label>Palier 1 : jusqu’au niveau <input name=\"heart_t1_max\" type=\"number\" min=\"1\"></label>\n          <label>Palier 1 : tickets par niveau <input name=\"heart_t1_mult\" type=\"number\" min=\"0\"></label>\n          <label>Palier 2 : jusqu’au niveau <input name=\"heart_t2_max\" type=\"number\" min=\"1\"></label>\n          <label>Palier 2 : tickets par niveau <input name=\"heart_t2_mult\" type=\"number\" min=\"0\"></label>\n          <label>Palier 3 : jusqu’au niveau (niveau max) <input name=\"heart_t3_max\" type=\"number\" min=\"1\"></label>\n          <label>Palier 3 : tickets par niveau <input name=\"heart_t3_mult\" type=\"number\" min=\"0\"></label>\n          <label>⭐ Tickets offerts aux Super Fans <input name=\"superfan_bonus\" type=\"number\" min=\"0\"></label>\n          <label>🪙 1 ticket tous les … pièces <span class=\"hint\">0 = désactivé</span><input name=\"coins_per_ticket\" type=\"number\" min=\"0\"></label>\n          <label class=\"full\">Texte d’introduction des règles (affiché sur le calendrier)\n            <textarea name=\"rules_intro\" maxlength=\"1000\"></textarea></label>\n          <p class=\"hint full\">🏆 Les tickets <b>mérite</b> s’ajoutent à la main pour chaque participant, dans « Participants & tickets » → ✏️ Modifier.</p>\n        </div>\n        <div class=\"actions\"><button class=\"btn-primary\" type=\"submit\">Enregistrer</button><span class=\"saved\" id=\"settings-saved\" hidden>Enregistré ✓</span></div>\n      </form>\n    </section>\n\n    <!-- Compte -->\n    <section data-panel=\"account\" hidden>\n      <h2>Compte</h2>\n      <p class=\"lead\">Change le code administrateur. Tu devras te reconnecter ensuite. Ne donne ce code qu’aux personnes de confiance.</p>\n      <form class=\"panel\" id=\"account-form\">\n        <div class=\"form-grid\">\n          <label class=\"full\">Code actuel <input name=\"current_code\" type=\"password\" autocomplete=\"current-password\" required></label>\n          <label>Nouveau code <span class=\"hint\">8 caractères minimum.</span>\n            <input name=\"new_code\" type=\"password\" autocomplete=\"new-password\" required></label>\n          <label>Confirmer le nouveau code <input name=\"confirm\" type=\"password\" autocomplete=\"new-password\" required></label>\n        </div>\n        <div class=\"actions\"><button class=\"btn-primary\" type=\"submit\">Mettre à jour</button></div>\n      </form>\n    </section>\n  </main>\n</div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n</body>\n</html>\n"
 },
 "admin.js": {
  "type": "text/javascript; charset=utf-8",
  "body": "// Tableau de bord administrateur. Toutes les données viennent d'API protégées côté serveur.\nconst $ = (id) => document.getElementById(id);\nlet CSRF = '';\n\nconst ICON_LABELS = {\n  etoile: 'Étoile', boule: 'Boule de Noël', sapin: 'Sapin', cadeau: 'Cadeau', cloche: 'Cloche', 'sucre-orge': 'Sucre d’orge',\n  houx: 'Houx', flocon: 'Flocon', chaussette: 'Chaussette', bougie: 'Bougie', couronne: 'Couronne', bonhomme: 'Bonhomme de neige',\n};\n\n// ---------- Utilitaires ----------\nfunction el(tag, props = {}, ...children) {\n  const e = document.createElement(tag);\n  for (const [k, v] of Object.entries(props)) {\n    if (k === 'class') e.className = v;\n    else if (k === 'text') e.textContent = v;\n    else if (k.startsWith('on')) e.addEventListener(k.slice(2), v);\n    else if (v !== false && v != null) e.setAttribute(k, v === true ? '' : v);\n  }\n  for (const c of children) if (c != null) e.append(c);\n  return e;\n}\n\nasync function api(url, { method = 'GET', body } = {}) {\n  const res = await fetch(url, {\n    method,\n    headers: method === 'GET' ? {} : { 'Content-Type': 'application/json', 'X-CSRF-Token': CSRF },\n    body: body ? JSON.stringify(body) : undefined,\n    cache: 'no-store',\n  });\n  if (res.status === 401) { location.href = '/admin/login'; throw new Error('Session expirée'); }\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw new Error(data.error || 'Erreur');\n  return data;\n}\n\nlet toastTimer;\nfunction toast(msg, isErr = false) {\n  const t = $('toast');\n  t.textContent = msg; t.className = `toast${isErr ? ' err' : ''}`; t.hidden = false;\n  clearTimeout(toastTimer); toastTimer = setTimeout(() => { t.hidden = true; }, 3000);\n}\n\nconst fmtDate = (s) => {\n  if (!s) return '';\n  const d = new Date(s.replace(' ', 'T') + 'Z');\n  return d.toLocaleString('fr-FR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });\n};\nconst nf = (n) => Number(n || 0).toLocaleString('fr-FR');\n\n// ---------- Onglets ----------\nconst loaders = {};\ndocument.querySelectorAll('.tab[data-tab]').forEach((b) => b.addEventListener('click', () => showTab(b.dataset.tab)));\nfunction showTab(name) {\n  document.querySelectorAll('.tab[data-tab]').forEach((b) => b.classList.toggle('active', b.dataset.tab === name));\n  document.querySelectorAll('[data-panel]').forEach((p) => { p.hidden = p.dataset.panel !== name; });\n  loaders[name]?.();\n}\n\n// ---------- Tableau de bord ----------\nlet todayDay = null;\nloaders.dashboard = async () => {\n  const s = await api('/api/admin/stats');\n  todayDay = s.today.day;\n  const line = { avant: 'Le calendrier n’a pas encore commencé.', apres: 'Le calendrier est terminé.', pendant: `Aujourd’hui : case n°${s.today.day}.` }[s.today.status];\n  $('today-line').textContent = `${line} Date utilisée : ${s.today.date}${s.today.testMode ? ' (date de test active ⚠️)' : ''}`;\n  $('s-visitors-today').textContent = nf(s.totals.visitorsToday);\n  $('s-visitors').textContent = nf(s.totals.visitors);\n  $('s-views').textContent = nf(s.totals.views);\n  $('s-participants').textContent = nf(s.totals.participants);\n  $('s-participations').textContent = nf(s.totals.participations);\n  $('s-tickets').textContent = nf(s.totals.tickets);\n  $('s-pending').textContent = nf(s.totals.pending);\n  $('s-validated').textContent = nf(s.totals.validated);\n\n  $('by-day').replaceChildren(...s.byDay.map((r) => el('tr', { class: r.day === todayDay ? 'today' : '' },\n    el('td', { text: `${r.day} déc.` }), el('td', { text: r.reward || '—' }),\n    el('td', { class: 'num', text: nf(r.opens) }), el('td', { class: 'num', text: nf(r.participants) }),\n    el('td', { class: 'num', text: nf(r.pending) }), el('td', { class: 'num', text: nf(r.validated) }),\n    el('td', { class: 'num', text: nf(r.tickets) }), el('td', { text: r.winner ? `@${r.winner}` : '—' }))));\n\n  $('visits').replaceChildren(...(s.visitsByDate.length ? s.visitsByDate.map((v) => el('tr', {},\n    el('td', { text: new Date(v.date + 'T12:00:00').toLocaleDateString('fr-FR', { weekday: 'short', day: 'numeric', month: 'long' }) }),\n    el('td', { class: 'num', text: nf(v.visitors) }), el('td', { class: 'num', text: nf(v.views) })))\n    : [el('tr', {}, el('td', { colspan: 3, class: 'empty', text: 'Aucune visite pour le moment.' }))]));\n};\n\n// ---------- Participants ----------\nfunction fillDaySelect(select, withAll) {\n  select.replaceChildren(...(withAll ? [el('option', { value: '', text: 'Tous les jours' })] : []),\n    ...Array.from({ length: 24 }, (_, i) => el('option', { value: i + 1, text: `${i + 1} décembre` })));\n}\nfillDaySelect($('p-day'), true);\nfillDaySelect($('d-day'), false);\n\nlet participations = [];\nloaders.participants = async () => {\n  const q = new URLSearchParams();\n  if ($('p-day').value) q.set('day', $('p-day').value);\n  if ($('p-status').value) q.set('status', $('p-status').value);\n  const data = await api(`/api/admin/participations?${q}`);\n  participations = data.participations;\n  renderParticipants();\n};\nfunction renderParticipants() {\n  const q = $('p-search').value.trim().toLowerCase();\n  const rows = participations.filter((p) => !q || p.pseudo.toLowerCase().includes(q));\n  const tickets = rows.reduce((a, p) => a + p.tickets, 0);\n  const cnt = (st) => rows.filter((p) => p.status === st).length;\n  $('p-summary').textContent = `${nf(rows.length)} participation${rows.length > 1 ? 's' : ''} · ${nf(tickets)} ticket${tickets > 1 ? 's' : ''} · ${nf(rows.filter((p) => p.top_fan).length)} Super Fan · ⏳ ${cnt('attente')} à valider · ✅ ${cnt('validee')} validée(s) · ❌ ${cnt('refusee')} refusée(s)`;\n  $('p-rows').replaceChildren(...(rows.length ? rows.map((p) => el('tr', {},\n    el('td', { text: `${p.day} déc.` }),\n    el('td', {}, el('a', { href: `https://www.tiktok.com/@${encodeURIComponent(p.pseudo)}`, target: '_blank', rel: 'noopener noreferrer', text: `@${p.pseudo}` })),\n    el('td', { class: 'num', text: `Niv. ${p.hearts}` }),\n    el('td', {}, el('span', { class: `pill ${p.top_fan ? 'oui' : 'non'}`, text: p.top_fan ? 'Oui' : 'Non' })),\n    el('td', { class: 'num', text: nf(p.coins) }),\n    el('td', { class: 'num', text: p.bonus ? (p.bonus > 0 ? `+${p.bonus}` : String(p.bonus)) : '—' }),\n    el('td', { class: 'num', text: p.tickets }),\n    el('td', { class: 'code', text: p.ticket_code }),\n    el('td', {}, el('span', { class: `status ${p.status}`, text: STATUS_LABELS[p.status] || p.status })),\n    el('td', { text: fmtDate(p.created_at) }),\n    el('td', {}, el('div', { class: 'row-actions' },\n      el('button', { class: 'btn-edit', text: '✏️ Modifier', onclick: () => openEdit(p) }),\n      p.status !== 'validee' ? el('button', { class: 'btn-ok', text: 'Valider', onclick: () => setStatus(p, 'validee') }) : null,\n      p.status !== 'refusee' ? el('button', { class: 'btn-no', text: 'Refuser', onclick: () => setStatus(p, 'refusee') }) : null,\n      p.status !== 'attente' ? el('button', { class: 'btn-ghost', text: '↺ En attente', title: 'Remettre en attente', onclick: () => setStatus(p, 'attente') }) : null,\n      el('button', { class: 'btn-danger', text: 'Supprimer', onclick: async () => {\n        if (!confirm(`Supprimer la participation de @${p.pseudo} (jour ${p.day}) ?`)) return;\n        try { await api(`/api/admin/participations/${p.id}`, { method: 'DELETE' }); toast('Participation supprimée'); loaders.participants(); }\n        catch (e) { toast(e.message, true); }\n      } })))))\n    : [el('tr', {}, el('td', { colspan: 11, class: 'empty', text: 'Aucune participation pour le moment.' }))]));\n}\n// ----- Modifier une participation (niveau, Super Fan, pièces, tickets mérite) -----\nlet editing = null, rulesCache = null;\nasync function getRules() {\n  if (!rulesCache) {\n    const { settings: st } = await api('/api/admin/settings');\n    const n = (k, d) => (Number.isFinite(Number(st[k])) && st[k] !== '' ? Number(st[k]) : d);\n    rulesCache = { tiers: [[n('heart_t1_max', 9), n('heart_t1_mult', 1)], [n('heart_t2_max', 19), n('heart_t2_mult', 2)], [n('heart_t3_max', 50), n('heart_t3_mult', 3)]],\n      superfan: n('superfan_bonus', 20), coinsPer: n('coins_per_ticket', 200) };\n  }\n  return rulesCache;\n}\nfunction calcTickets(r, level, fan, coins, bonus) {\n  const tier = r.tiers.find(([max]) => level <= max) || r.tiers[r.tiers.length - 1];\n  return Math.max(1, level * tier[1] + (fan ? r.superfan : 0) + (r.coinsPer > 0 ? Math.floor(coins / r.coinsPer) : 0) + bonus);\n}\nasync function openEdit(p) {\n  editing = p;\n  const f = $('edit-form');\n  f.elements.hearts.value = p.hearts; f.elements.coins.value = p.coins || 0;\n  f.elements.top_fan.checked = Boolean(p.top_fan); f.elements.bonus.value = p.bonus || 0;\n  $('edit-title').textContent = `Modifier @${p.pseudo} (jour ${p.day})`;\n  $('edit-box').hidden = false;\n  await refreshEditTotal();\n}\nasync function refreshEditTotal() {\n  const f = $('edit-form'), r = await getRules();\n  const t = calcTickets(r, Number(f.elements.hearts.value) || 0, f.elements.top_fan.checked, Number(f.elements.coins.value) || 0, Number(f.elements.bonus.value) || 0);\n  $('edit-total').textContent = `🎟️ Total : ${t} ticket${t > 1 ? 's' : ''}`;\n}\n$('edit-form').addEventListener('input', refreshEditTotal);\n$('edit-cancel').addEventListener('click', () => { $('edit-box').hidden = true; });\n$('edit-form').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const f = e.target;\n  try {\n    const r = await api(`/api/admin/participations/${editing.id}`, { method: 'PUT', body: {\n      hearts: Number(f.elements.hearts.value) || 0, coins: Number(f.elements.coins.value) || 0,\n      top_fan: f.elements.top_fan.checked, bonus: Number(f.elements.bonus.value) || 0,\n    } });\n    Object.assign(editing, r.participation);\n    $('edit-box').hidden = true;\n    renderParticipants();\n    toast('Participation mise à jour');\n  } catch (err) { toast(err.message, true); }\n});\n\nconst STATUS_LABELS = { attente: '⏳ À valider', validee: '✅ Validée', refusee: '❌ Refusée' };\nasync function setStatus(p, status) {\n  try {\n    await api(`/api/admin/participations/${p.id}`, { method: 'PUT', body: { status } });\n    p.status = status;\n    renderParticipants();\n  } catch (e) { toast(e.message, true); }\n}\n$('p-day').addEventListener('change', () => loaders.participants());\n$('p-status').addEventListener('change', () => loaders.participants());\n$('p-validate-all').addEventListener('click', async () => {\n  const day = $('p-day').value;\n  if (!day) return toast('Choisis d’abord un jour dans la liste « Jour ».', true);\n  if (!confirm(`Valider toutes les participations en attente du ${day} décembre ?`)) return;\n  try {\n    const r = await api('/api/admin/participations/validate-all', { method: 'POST', body: { day: Number(day) } });\n    toast(`${r.changed} participation(s) validée(s)`);\n    loaders.participants();\n  } catch (e) { toast(e.message, true); }\n});\n$('p-search').addEventListener('input', renderParticipants);\n$('p-refresh').addEventListener('click', () => loaders.participants());\n\n// ---------- Roue du tirage ----------\nlet rewards = {};\nlet wheelEntries = [];      // [{pseudo, tickets, manual}]\nlet manualNames = [];      // [{ pseudo, tickets }]\nlet rot = 0;                // rotation actuelle de la roue (radians)\nlet spinning = false;\nlet lastDraw = null;\nconst SEG_COLORS = ['#c8102e', '#0f3b2b', '#e6c068', '#1b5a41', '#8e0b20', '#f7f4ec'];\nconst TEXT_ON = { '#e6c068': '#2a1c05', '#f7f4ec': '#2a1c05' };\n\nfunction drawOptions() {\n  return {\n    include_auto: $('w-auto').checked,\n    validated_only: $('d-validated').checked,\n    exclude_previous_winners: $('d-exclude').checked,\n    manual: manualNames,\n  };\n}\n\nloaders.draw = async () => {\n  if (!Object.keys(rewards).length) {\n    const c = await api('/api/admin/cases');\n    c.cases.forEach((x) => { rewards[x.day] = x.reward; });\n  }\n  if (todayDay && !$('d-day').dataset.touched) $('d-day').value = todayDay;\n  $('d-reward').textContent = `🎁 Lot : ${rewards[$('d-day').value] || '—'}`;\n  await refreshWheel();\n  await loadHistory();\n};\n\nasync function refreshWheel() {\n  if (spinning) return;\n  try {\n    const r = await api(`/api/admin/wheel/${$('d-day').value}`, { method: 'POST', body: drawOptions() });\n    wheelEntries = r.entries;\n  } catch (e) { toast(e.message, true); wheelEntries = []; }\n  renderChips();\n  const tickets = wheelEntries.reduce((a, e) => a + e.tickets, 0);\n  $('w-count').textContent = wheelEntries.length\n    ? `${wheelEntries.length} personne(s) sur la roue · ${tickets} ticket(s)${manualNames.length ? ` · dont ${manualNames.reduce((a, m) => a + m.tickets, 0)} ajouté(s) à la main` : ''}`\n    : 'La roue est vide : valide des participations ou ajoute des pseudos à la main.';\n  drawWheel();\n  $('w-live').textContent = wheelEntries.length ? '—' : 'Roue vide';\n}\n\nfunction segments() {\n  const total = wheelEntries.reduce((a, e) => a + e.tickets, 0) || 1;\n  let acc = 0;\n  return wheelEntries.map((e, i) => {\n    const span = (e.tickets / total) * Math.PI * 2;\n    const seg = { ...e, start: acc, end: acc + span, color: SEG_COLORS[i % SEG_COLORS.length] };\n    acc += span;\n    return seg;\n  });\n}\n\nfunction drawWheel() {\n  const cv = $('wheel');\n  const ctx = cv.getContext('2d');\n  const W = cv.width, R = W / 2 - 8, c = W / 2;\n  ctx.clearRect(0, 0, W, W);\n  // anneau doré\n  ctx.beginPath(); ctx.arc(c, c, R + 6, 0, Math.PI * 2); ctx.fillStyle = '#b8862b'; ctx.fill();\n  const segs = segments();\n  if (!segs.length) {\n    ctx.beginPath(); ctx.arc(c, c, R, 0, Math.PI * 2); ctx.fillStyle = '#16261f'; ctx.fill();\n    return;\n  }\n  const base = -Math.PI / 2 + rot;\n  const many = segs.length > 60;\n  for (const sg of segs) {\n    ctx.beginPath(); ctx.moveTo(c, c);\n    ctx.arc(c, c, R, base + sg.start, base + sg.end); ctx.closePath();\n    ctx.fillStyle = sg.color; ctx.fill();\n    ctx.strokeStyle = 'rgba(0,0,0,.25)'; ctx.lineWidth = 1; ctx.stroke();\n    const span = sg.end - sg.start;\n    if (!many && span > 0.06) {\n      ctx.save();\n      ctx.translate(c, c); ctx.rotate(base + sg.start + span / 2);\n      ctx.textAlign = 'right'; ctx.textBaseline = 'middle';\n      ctx.fillStyle = TEXT_ON[sg.color] || '#fff';\n      const size = Math.max(11, Math.min(22, span * R * 0.55));\n      ctx.font = `700 ${size}px system-ui, sans-serif`;\n      const label = sg.pseudo.length > 16 ? sg.pseudo.slice(0, 15) + '…' : sg.pseudo;\n      ctx.fillText(label, R - 16, 0);\n      ctx.restore();\n    }\n  }\n  // petites lumières sur le bord\n  for (let i = 0; i < 36; i++) {\n    const a = (i / 36) * Math.PI * 2 + rot;\n    ctx.beginPath(); ctx.arc(c + Math.cos(a) * (R + 1), c + Math.sin(a) * (R + 1), 3, 0, Math.PI * 2);\n    ctx.fillStyle = i % 2 ? '#fff3c4' : '#ffd36b'; ctx.fill();\n  }\n}\n\n// Pseudo actuellement sous la flèche\nfunction entryAtPointer() {\n  const segs = segments();\n  const a = ((-rot) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2);\n  return segs.find((sg) => a >= sg.start && a < sg.end) || segs[segs.length - 1];\n}\n\nlet audioCtx = null;\nfunction tick() {\n  try {\n    audioCtx = audioCtx || new AudioContext();\n    const o = audioCtx.createOscillator(), g = audioCtx.createGain();\n    o.frequency.value = 1400; o.type = 'triangle';\n    g.gain.setValueAtTime(0.08, audioCtx.currentTime);\n    g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + 0.05);\n    o.connect(g).connect(audioCtx.destination); o.start(); o.stop(audioCtx.currentTime + 0.06);\n  } catch { /* son indisponible */ }\n}\n\nasync function spin() {\n  if (spinning) return;\n  const day = $('d-day').value;\n  spinning = true;\n  $('w-spin').disabled = true; $('w-spin-center').disabled = true;\n  $('w-result').hidden = true;\n  try {\n    // Le gagnant est tiré au sort par le serveur ; la roue s'arrête ensuite sur lui\n    const r = await api(`/api/admin/draw/${day}`, { method: 'POST', body: drawOptions() });\n    wheelEntries = r.entries;\n    const segs = segments();\n    const target = segs[r.index];\n    const inside = target.start + (target.end - target.start) * (0.15 + Math.random() * 0.7);\n    const full = Math.PI * 2;\n    const current = ((rot % full) + full) % full;\n    let delta = ((-inside - current) % full + full) % full;\n    delta += full * (6 + Math.floor(Math.random() * 3));\n    const startRot = rot, duration = 7000, t0 = performance.now();\n    let lastName = null;\n    await new Promise((resolve) => {\n      const frame = (now) => {\n        const t = Math.min(1, (now - t0) / duration);\n        const ease = 1 - Math.pow(1 - t, 4);\n        rot = startRot + delta * ease;\n        drawWheel();\n        const cur = entryAtPointer();\n        if (cur && cur.pseudo !== lastName) { lastName = cur.pseudo; $('w-live').textContent = `@${cur.pseudo}`; tick(); }\n        if (t < 1) requestAnimationFrame(frame); else resolve();\n      };\n      requestAnimationFrame(frame);\n    });\n    lastDraw = { id: r.draw_id, winner: r.winner, day };\n    showWinner(r.winner, day);\n  } catch (e) {\n    toast(e.message, true);\n  } finally {\n    spinning = false;\n    $('w-spin').disabled = false; $('w-spin-center').disabled = false;\n  }\n}\n\nfunction showWinner(w, day) {\n  $('w-name').textContent = `@${w.pseudo}`;\n  $('w-meta').textContent = `Lot du ${day} décembre : ${rewards[day] || '—'} · ${w.tickets} ticket(s) sur ${w.total_tickets} · ${w.participants} personne(s) sur la roue${w.manual ? ' · ajouté à la main' : ''}`;\n  $('w-note').textContent = '';\n  $('w-confirm').disabled = false;\n  $('w-confirm').textContent = '✅ Confirmer ce gagnant';\n  $('w-result').hidden = false;\n  confettiAdmin();\n}\n\n$('w-spin').addEventListener('click', spin);\n$('w-spin-center').addEventListener('click', spin);\n$('w-again').addEventListener('click', () => { $('w-result').hidden = true; spin(); });\n$('w-close').addEventListener('click', () => { $('w-result').hidden = true; });\n$('w-copy').addEventListener('click', async () => {\n  const txt = lastDraw ? lastDraw.winner.pseudo : '';\n  try { await navigator.clipboard.writeText(txt); }\n  catch {\n    const ta = document.createElement('textarea'); ta.value = txt; document.body.append(ta); ta.select();\n    document.execCommand('copy'); ta.remove();\n  }\n  $('w-note').textContent = `Pseudo « ${txt} » copié ✓`;\n});\n$('w-confirm').addEventListener('click', async () => {\n  if (!lastDraw) return;\n  try {\n    await api(`/api/admin/draws/${lastDraw.id}/confirm`, { method: 'POST', body: {} });\n    $('w-confirm').disabled = true;\n    $('w-confirm').textContent = 'Gagnant confirmé ✓';\n    $('w-note').textContent = lastDraw.winner.manual\n      ? 'Confirmé ! Comme ce pseudo a été ajouté à la main, préviens-le directement sur TikTok.'\n      : 'Confirmé ! Le gagnant verra un message de victoire à sa prochaine visite sur le site.';\n    loadHistory();\n  } catch (e) { toast(e.message, true); }\n});\n\nfunction renderChips() {\n  $('w-manual').replaceChildren(...manualNames.map((m) => {\n    const change = (delta) => { m.tickets = Math.max(1, m.tickets + delta); refreshWheel(); };\n    return el('span', { class: 'chip' }, `@${m.pseudo}`,\n      el('span', { class: 'chip-tk', title: 'Tickets ajoutés' },\n        el('button', { type: 'button', 'aria-label': `Un ticket de moins pour ${m.pseudo}`, text: '−', onclick: () => change(-1) }),\n        `${m.tickets} 🎟️`,\n        el('button', { type: 'button', 'aria-label': `Un ticket de plus pour ${m.pseudo}`, text: '+', onclick: () => change(1) })),\n      el('button', { type: 'button', 'aria-label': `Retirer ${m.pseudo}`, text: '×', onclick: () => { manualNames = manualNames.filter((x) => x !== m); refreshWheel(); } }));\n  }));\n}\nfunction ticketField() {\n  const n = Math.floor(Number($('w-add-tickets').value));\n  return Number.isFinite(n) && n >= 1 ? Math.min(n, 100000) : 1;\n}\nfunction setTicketField(n) {\n  $('w-add-tickets').value = Math.max(1, Math.min(100000, n));\n  document.querySelectorAll('#w-tk-quick button').forEach((b) => b.classList.toggle('on', Number(b.dataset.tk) === Number($('w-add-tickets').value)));\n}\nfunction addManual() {\n  const raw = $('w-add-input').value;\n  const def = ticketField();\n  const items = raw.split(/[\\n,;]+/).map((x) => x.trim()).filter(Boolean).map((x) => {\n    // « pseudo:15 » ou « pseudo 15 » = 15 tickets pour cette personne\n    const m = /^@?([^\\s:]+)\\s*[:\\s]\\s*(\\d+)$/.exec(x);\n    return m ? { pseudo: m[1], tickets: Math.max(1, Number(m[2])) } : { pseudo: x.replace(/^@+/, '').split(/\\s+/)[0], tickets: def };\n  }).filter((it) => it.pseudo);\n  for (const it of items) {\n    const ex = manualNames.find((x) => x.pseudo.toLowerCase() === it.pseudo.toLowerCase());\n    if (ex) ex.tickets += it.tickets; else manualNames.push({ pseudo: it.pseudo.slice(0, 40), tickets: it.tickets });\n  }\n  if (items.length) toast(items.length === 1 ? `@${items[0].pseudo} ajouté avec ${items[0].tickets} ticket(s)` : `${items.length} pseudos ajoutés`);\n  $('w-add-input').value = '';\n  refreshWheel();\n}\n$('w-tk-minus').addEventListener('click', () => setTicketField(ticketField() - 1));\n$('w-tk-plus').addEventListener('click', () => setTicketField(ticketField() + 1));\n$('w-add-tickets').addEventListener('input', () => setTicketField(ticketField()));\ndocument.querySelectorAll('#w-tk-quick button').forEach((b) => b.addEventListener('click', () => setTicketField(Number(b.dataset.tk))));\nsetTicketField(1);\n$('w-add').addEventListener('click', addManual);\n$('w-add-input').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); addManual(); } });\n$('w-add-input').addEventListener('paste', () => setTimeout(() => { if (/[\\n,;]/.test($('w-add-input').value)) addManual(); }, 0));\n$('w-clear').addEventListener('click', () => { manualNames = []; refreshWheel(); });\n['w-auto', 'd-validated', 'd-exclude'].forEach((id) => $(id).addEventListener('change', refreshWheel));\n$('d-day').addEventListener('change', () => {\n  $('d-day').dataset.touched = '1';\n  $('d-reward').textContent = `🎁 Lot : ${rewards[$('d-day').value] || '—'}`;\n  refreshWheel();\n});\n\nasync function loadHistory() {\n  const h = await api('/api/admin/draws');\n  $('d-history').replaceChildren(...(h.draws.length ? h.draws.map((d) => el('tr', {},\n    el('td', { text: `${d.day} déc.` }), el('td', { text: d.reward }), el('td', { text: `@${d.pseudo}` }),\n    el('td', { class: 'code', text: d.ticket_code || '—' }),\n    el('td', {}, el('span', { class: d.manual ? 'no-pill' : 'ok-pill', text: d.manual ? 'Ajout manuel (à prévenir sur TikTok)' : d.seen ? 'Vu par le gagnant ✓' : 'En attente de sa visite' })),\n    el('td', { text: fmtDate(d.created_at) }),\n    el('td', {}, el('button', { class: 'btn-danger', text: 'Annuler', onclick: async () => {\n      if (!confirm(`Annuler la victoire de @${d.pseudo} ?`)) return;\n      await api(`/api/admin/draws/${d.id}`, { method: 'DELETE' }); loadHistory();\n    } }))))\n    : [el('tr', {}, el('td', { colspan: 7, class: 'empty', text: 'Aucun gagnant confirmé pour le moment.' }))]));\n}\n\nfunction confettiAdmin() {\n  const canvas = $('w-confetti');\n  const ctx = canvas.getContext('2d');\n  const W = canvas.width = innerWidth, H = canvas.height = innerHeight;\n  const colors = ['#e6c068', '#fff3c4', '#c8102e', '#f7f4ec', '#2f8a5b', '#25f4ee', '#fe2c55'];\n  const parts = Array.from({ length: 200 }, () => ({\n    x: Math.random() * W, y: -20 - Math.random() * H, w: 6 + Math.random() * 8, h: 8 + Math.random() * 10,\n    vy: 2.5 + Math.random() * 3.5, vx: -1.5 + Math.random() * 3, r: Math.random() * 3, vr: -.1 + Math.random() * .2,\n    c: colors[Math.floor(Math.random() * colors.length)],\n  }));\n  const end = performance.now() + 6000;\n  (function frame(now) {\n    ctx.clearRect(0, 0, W, H);\n    for (const p of parts) {\n      p.y += p.vy; p.x += p.vx; p.r += p.vr;\n      if (p.y > H + 20 && now < end) { p.y = -20; p.x = Math.random() * W; }\n      ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.r); ctx.fillStyle = p.c; ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h); ctx.restore();\n    }\n    if (now < end + 3000 && !$('w-result').hidden) requestAnimationFrame(frame); else ctx.clearRect(0, 0, W, H);\n  })(performance.now());\n}\n\n// ---------- Cases & lots ----------\nloaders.cases = async () => {\n  const { cases, icons } = await api('/api/admin/cases');\n  cases.forEach((x) => { rewards[x.day] = x.reward; });\n  $('case-list').replaceChildren(...cases.map((c) => caseEditor(c, icons)));\n};\nfunction caseEditor(c, icons) {\n  const summaryTitle = el('b', { text: c.title || `Case ${c.day}` });\n  const summaryReward = el('small', { text: c.reward ? `🎁 ${c.reward}` : 'Pas de lot' });\n  const field = (label, input, full = true, hint) => el('label', { class: full ? 'full' : '' }, label, hint ? el('span', { class: 'hint', text: hint }) : null, input);\n  const inp = (name, value, extra = {}) => el('input', { name, value: value || '', ...extra });\n\n  const iconSel = el('select', { name: 'icon' }, ...icons.map((i) => el('option', { value: i, text: ICON_LABELS[i] || i, selected: i === c.icon })));\n  const msg = el('textarea', { name: 'message', maxlength: 3000 }); msg.value = c.message;\n  const saved = el('span', { class: 'saved', text: 'Enregistré ✓', hidden: true });\n\n  const form = el('form', {},\n    el('div', { class: 'form-grid' },\n      field('Lot / récompense (gros titre)', inp('reward', c.reward, { maxlength: 300 }), false),\n      field('Pastille sous le lot', inp('subtitle', c.subtitle, { maxlength: 80, placeholder: 'Une heure rien que pour toi' }), false),\n      field('Couleur de la pastille', el('select', { name: 'accent' }, ...[['rouge', 'Rouge'], ['vert', 'Vert'], ['violet', 'Violet'], ['noir', 'Noir'], ['bleu', 'Bleu'], ['or', 'Doré']]\n        .map(([v, t]) => el('option', { value: v, text: t, selected: v === (c.accent || 'or') }))), false),\n      field('Décoration de la case', iconSel, false),\n      field('Titre affiché', inp('title', c.title, { maxlength: 120 })),\n      field('Message', msg),\n      field('Photo du lot (optionnel)', inp('image_url', c.image_url, { placeholder: 'https://… ou /img/…' }), true, 'Photos fournies : /img/passe-de-combat.webp, /img/figurine-pop.webp, /img/peluche-tiktok.webp'),\n      field('Lien (optionnel)', inp('link_url', c.link_url, { type: 'url', placeholder: 'https://www.tiktok.com/@…' }), false),\n      field('Texte du bouton du lien', inp('link_label', c.link_label, { maxlength: 60, placeholder: 'Rejoindre le live' }), false)),\n    el('div', { class: 'actions' }, el('button', { class: 'btn-primary', type: 'submit', text: 'Enregistrer la case' }), saved));\n\n  form.addEventListener('submit', async (e) => {\n    e.preventDefault();\n    const body = Object.fromEntries(new FormData(form));\n    try {\n      const r = await api(`/api/admin/cases/${c.day}`, { method: 'PUT', body });\n      summaryTitle.textContent = r.case.title || `Case ${c.day}`;\n      summaryReward.textContent = r.case.reward ? `🎁 ${r.case.reward}` : 'Pas de lot';\n      rewards[c.day] = r.case.reward;\n      saved.hidden = false; setTimeout(() => { saved.hidden = true; }, 2000);\n    } catch (err) { toast(err.message, true); }\n  });\n\n  return el('details', { class: 'case-item' },\n    el('summary', {}, el('span', { class: 'd', text: c.day }), el('span', { class: 't' }, summaryTitle, summaryReward), el('span', { class: 'muted', text: 'Modifier ▾' })),\n    form);\n}\n\n// ---------- Réglages ----------\nloaders.settings = async () => {\n  const { settings } = await api('/api/admin/settings');\n  const f = $('settings-form');\n  for (const [k, v] of Object.entries(settings)) {\n    const input = f.elements[k];\n    if (!input) continue;\n    if (input.type === 'checkbox') input.checked = v === '1'; else input.value = v;\n  }\n};\n$('settings-form').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const f = e.target;\n  const body = Object.fromEntries(new FormData(f));\n  body.participation_open = f.elements.participation_open.checked;\n  body.music_enabled = f.elements.music_enabled.checked;\n  try {\n    await api('/api/admin/settings', { method: 'PUT', body });\n    rulesCache = null;\n    $('settings-saved').hidden = false; setTimeout(() => { $('settings-saved').hidden = true; }, 2000);\n  } catch (err) { toast(err.message, true); }\n});\n\n// ---------- Compte ----------\n$('account-form').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const body = Object.fromEntries(new FormData(e.target));\n  if (body.new_code !== body.confirm) return toast('Les deux nouveaux codes ne correspondent pas.', true);\n  delete body.confirm;\n  try {\n    await api('/api/admin/account', { method: 'PUT', body });\n    alert('Code mis à jour. Reconnecte-toi avec le nouveau code.');\n    location.href = '/admin/login';\n  } catch (err) { toast(err.message, true); }\n});\n\n$('logout').addEventListener('click', async () => {\n  try { await api('/api/admin/logout', { method: 'POST', body: {} }); } finally { location.href = '/admin/login'; }\n});\n\n// ---------- Démarrage ----------\n(async () => {\n  const me = await api('/api/admin/me');\n  CSRF = me.csrf;\n  $('who').textContent = 'Connecté en administrateur';\n  showTab('dashboard');\n})();\n"
 },
 "login.html": {
  "type": "text/html; charset=utf-8",
  "body": "<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <title>Connexion administrateur</title>\n  <link rel=\"stylesheet\" href=\"/admin/admin.css\">\n  <script type=\"module\" src=\"/admin/login.js\"></script>\n</head>\n<body class=\"login-page\">\n  <form class=\"login-card\" id=\"login-form\" novalidate>\n    <div class=\"login-logo\">🎄</div>\n    <h1>Espace administrateur</h1>\n    <p class=\"muted\">Accès réservé.</p>\n    <label>Code administrateur\n      <input type=\"password\" id=\"code\" autocomplete=\"current-password\" required autofocus>\n    </label>\n    <p class=\"error\" id=\"error\" role=\"alert\" hidden></p>\n    <button class=\"btn-primary\" type=\"submit\" id=\"submit\">Se connecter</button>\n    <a class=\"back\" href=\"/\">← Retour au calendrier</a>\n  </form>\n</body>\n</html>\n"
 },
 "login.js": {
  "type": "text/javascript; charset=utf-8",
  "body": "const form = document.getElementById('login-form');\nconst err = document.getElementById('error');\n\nform.addEventListener('submit', async (e) => {\n  e.preventDefault();\n  err.hidden = true;\n  const btn = document.getElementById('submit');\n  btn.disabled = true;\n  try {\n    const res = await fetch('/api/admin/login', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ code: document.getElementById('code').value }),\n    });\n    const data = await res.json();\n    if (res.ok) { location.href = '/admin'; return; }\n    err.textContent = data.error || 'Connexion impossible.';\n    err.hidden = false;\n  } catch {\n    err.textContent = 'Problème de connexion au serveur.';\n    err.hidden = false;\n  } finally {\n    btn.disabled = false;\n  }\n});\n"
 }
};
